(7108547, 1084172, 117534, '<td valign="top">Adorable!!!! Well I guess he''s handsome, but the whole shot, editing, accordion, etc.. it''s &lt;- see first word</td>', 'Adorable!!!! Well I guess he''s handsome, but the whole shot, editing, accordion, etc.. it''s <- see first word', '2013-09-30 01:03:30.000000', NULL, 1),
