(7108551, 1084271, 23484, '<td valign="top">Yes, he does look happy with himself.</td>', 'Yes, he does look happy with himself.', '2013-09-30 01:07:00.000000', NULL, 1),
(7108552, 1084325, 23484, '<td valign="top">Fantastic candid shot.</td>', 'Fantastic candid shot.', '2013-09-30 01:07:18.000000', NULL, 1),
