(7108558, 1084377, 23484, '<td valign="top">I really like the processing.</td>', 'I really like the processing.', '2013-09-30 01:09:53.000000', NULL, 1),
(7108560, 1084282, 117534, '<td valign="top">Very Norman Rockwellish... I really like it!!  If I may add one little critique that would''ve made this a total 10 from me, Normans pictures are quite "poppy" this feels a little soft in the focus, I think popping the contrast up a bit, and maybe a bit sharper (OH I can''t believe I said that, I am the queen of over sharp have to work hard to get mine softer) LOL Any how, just my 2 cent''s I''m still giving u and 8 because it is lovely!</td>', 'Very Norman Rockwellish... I really like it!!  If I may add one little critique that would''ve made this a total 10 from me, Normans pictures are quite "poppy" this feels a little soft in the focus, I think popping the contrast up a bit, and maybe a bit sharper (OH I can''t believe I said that, I am the queen of over sharp have to work hard to get mine softer) LOL Any how, just my 2 cent''s I''m still giving u and 8 because it is lovely!', '2013-09-30 01:11:07.000000', NULL, 1),
(7108648, 1084282, 85102, '<td valign="top">Cute idea! But it appears as though the children were cut out of another pictures and pasted on a white background. The edges are not natural and the lack of shadows makes it seem like they''re floating in nothingness. It''s a little intense for the eye. But definitely a cute idea</td>', 'Cute idea! But it appears as though the children were cut out of another pictures and pasted on a white background. The edges are not natural and the lack of shadows makes it seem like they''re floating in nothingness. It''s a little intense for the eye. But definitely a cute idea', '2013-09-30 04:35:17.000000', NULL, 1),
(7108649, 1084042, 85102, '<td valign="top">The editing is a bit intense for my taste-- the skin tones look like a painting and the detail in the fence behind is a bit distracting. But very cute idea and great capture.</td>', 'The editing is a bit intense for my taste-- the skin tones look like a painting and the detail in the fence behind is a bit distracting. But very cute idea and great capture.', '2013-09-30 04:37:41.000000', NULL, 1),
(7108650, 1084480, 85102, '<td valign="top">Very simple but adorable and perfect for the challenge</td>', 'Very simple but adorable and perfect for the challenge', '2013-09-30 04:38:00.000000', NULL, 1),
(7108651, 1084518, 85102, '<td valign="top">Great pictures! I can''t see his smile so well but I do think if I was in his (biking) shoes I''d certainly be smiling so I took that into consideration for my vote!</td>', 'Great pictures! I can''t see his smile so well but I do think if I was in his (biking) shoes I''d certainly be smiling so I took that into consideration for my vote!', '2013-09-30 04:39:46.000000', NULL, 1),
(7108655, 1084172, 85102, '<td valign="top">Such a genuine smile! I love it. The lighting is just a WEE bit intense for my liking, but at least it allowed you to catch all his brilliant smile lines</td>', 'Such a genuine smile! I love it. The lighting is just a WEE bit intense for my liking, but at least it allowed you to catch all his brilliant smile lines', '2013-09-30 04:40:49.000000', NULL, 1),
(7108656, 1084377, 85102, '<td valign="top">Brilliant smile! I just wish there wasn''t quite so much film grain...</td>', 'Brilliant smile! I just wish there wasn''t quite so much film grain...', '2013-09-30 04:41:31.000000', NULL, 1),
