(7112037, 1084325, 108069, '<td valign="top">Spoken like Oscar Wilde. Great contrast of emotions in the photo, and nicely processed to show it off.</td>', 'Spoken like Oscar Wilde. Great contrast of emotions in the photo, and nicely processed to show it off.', '2013-10-07 00:20:08.000000', NULL, 1),
(7112038, 1084385, 37999, '<td valign="top">I found this photo a little to dark in the contrast zone. The male on the left of the girl. His shirt and his hair is so dark there is not definition. I think you have a great idea here and composed rather well!</td>', 'I found this photo a little to dark in the contrast zone. The male on the left of the girl. His shirt and his hair is so dark there is not definition. I think you have a great idea here and composed rather well!', '2013-10-07 00:22:04.000000', NULL, 1),
(7112040, 1084498, 37999, '<td valign="top">The composition and lighting are off here. I would lighten up the photo. And general when you have a person facing to the right it is better to stage them on the left.</td>', 'The composition and lighting are off here. I would lighten up the photo. And general when you have a person facing to the right it is better to stage them on the left.', '2013-10-07 00:25:59.000000', NULL, 1),
(7112041, 1084351, 37999, '<td valign="top">I just, I, I LOVE IT!</td>', 'I just, I, I LOVE IT!', '2013-10-07 00:28:47.000000', NULL, 1),
(7112042, 1084517, 37999, '<td valign="top">Nice, Nice photo. There are a couple of floaty spots on her right are that I think you could have fixed and still maintained the look. That is about the only think that is drawing my eye away. Good Job!</td>', 'Nice, Nice photo. There are a couple of floaty spots on her right are that I think you could have fixed and still maintained the look. That is about the only think that is drawing my eye away. Good Job!', '2013-10-07 00:30:48.000000', NULL, 1),
(7112043, 1084042, 37999, '<td valign="top">Creepy smile vs. cute smile = adorable storytelling photo. Your title fits the the photo perfectly. I really like this photo, it''s got a content depth and can most likely be interpreted in so many ways which is what photography and art is all about. Way to Go!</td>', 'Creepy smile vs. cute smile = adorable storytelling photo. Your title fits the the photo perfectly. I really like this photo, it''s got a content depth and can most likely be interpreted in so many ways which is what photography and art is all about. Way to Go!', '2013-10-07 00:33:32.000000', NULL, 1),
